import { useQuery } from '@tanstack/react-query';
import { downloadCsv } from '../../api/csv';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import { personDue, ratesQuery } from '../rates/ratesQuery';
import { useCap, useFloor, useLate } from '../settings/settingsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { gradeOn, peopleQuery } from './peopleQuery';

/** Downloads the people as CSV, in list order and retired people included, with the figures the screen shows. */
function ExportPeople({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);

  const exportCsv = () => {
    downloadCsv('people.csv', [
      ['name', 'grade', 'retired-from', 'due-total'],
      ...people.map((p) => [p.name, gradeOn(p, today) ?? p.grade, p.retiredFrom ?? '', personDue(p, people, claims, rates, today, floor, late, cap)]),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={exportCsv}>
        Export people (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 11, Component: ExportPeople });
import { getJson } from '../../api/http';
import { heldOn, type Person } from '../people/peopleQuery';
import { sheetKey } from '../sheet/sheetQuery';

/** REVIEW: opened with a due above the review threshold in force on its date; unnumbered and counting in no total until a steward's review makes it OPEN. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';

/** An open claim: OPEN, or PENDING (settled by a clerk above the clerk limit, awaiting a steward), handled like OPEN in every total. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * `amount` has two decimals ("12.50"); `date` is yyyy-mm-dd; `number` is given on opening and kept when voided (null for a draft);
 * `settledDue` is the due fixed on settling (null when not settled, or settled while no rate applied on the claim's date);
 * `openedBy` is the user who opened it (null when never opened), who cannot settle it;
 * `stated` is whether its person's last statement bound it, at `statedDue` (null when it had no figure then) — a PENDING claim too;
 * a negative `amount` is a correction, and `corrects` is the number of the settled claim it corrects (null for any other claim);
 * `dueBy` (yyyy-mm-dd) is fixed when the claim is made, from its person's own terms, else the terms of their grade on its date, counted in business days after its date (skipping Saturdays, Sundays and the sheet's holidays as they then were), and kept when they or its date change;
 * `log` is its status log, oldest first, one line per status it has had: "<STATUS> by <user> on <date> due=<due>";
 * `deferredUntil` (yyyy-mm-dd) is the date an OPEN claim was deferred to (null when never deferred), see `isDeferred`;
 * `proofs` is how many proofs it has been given: one above the sheet's proof threshold is settled or approved only with one (of each of the sheet's proof kinds, while it has them);
 * `proofsReceipt` and `proofsPhoto` are how many of them are receipts and photos;
 * `splitFrom` is the number of the claim it was split off (null for any other claim);
 * `lockedBy` is the user whose open editor locks it for everyone else (null when not locked);
 * `lateEntry` is whether it was added while the period its due-by falls in was soft-closed;
 * `remindedOn` (yyyy-mm-dd) is the last sheet's today a reminder was written for it (null when never reminded);
 * `ref` is its external reference, unique on the sheet without regard to case (null when it has none);
 * `tags` are its tags, trimmed, lower-cased, without repeats and sorted (empty for none);
 * `comments` are its comments, oldest first, each "<user> on <date>: <text>" with the sheet's today when written;
 * `batch` is the number of the settle batch (a bulk settle) that settled it (null when none, or settled one at a time);
 * `reviewOn` (yyyy-mm-dd) is the sheet's today it last went to REVIEW (null when it never did);
 * `lines` are its lines, in the order added, each "<label> <qty> x <unit>" (a DRAFT's amount is then their sum);
 * `waived` is whether a steward waived its late charge: it bears none from then on;
 * `held` is whether it is held: while open and not bound by a statement it counts in no due figure (it still counts in claimed), as a held person's claims do.
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: string[];
  deferredUntil: string | null;
  proofs: number;
  proofsReceipt: number;
  proofsPhoto: number;
  splitFrom: string | null;
  lockedBy: string | null;
  lateEntry: boolean;
  remindedOn: string | null;
  ref: string | null;
  tags: string[];
  comments: string[];
  batch: number | null;
  lines: string[];
  reviewOn: string | null;
  waived: boolean;
  held: boolean;
};

/** Whether a REVIEW claim is late: its review day plus the review SLA's days (`sla`, "" for none) is before the sheet's `today`. */
export const isReviewLate = (c: Claim, today: string, sla: string) => {
  if (c.status !== 'REVIEW' || c.reviewOn === null || sla === '' || today === '') return false;
  const due = new Date(`${c.reviewOn}T00:00:00Z`);
  due.setUTCDate(due.getUTCDate() + Number(sla));
  return due.toISOString().slice(0, 10) < today;
};

/** A correction: its due is its amount times the rate, with no floor and no late charge. */
export const isCorrection = (c: Claim) => Number(c.amount) < 0;

/**
 * An OPEN claim deferred to a date the sheet's `today` has not reached: it counts in no total, is not overdue and
